import java.io.File;
import java.util.EnumSet;

public class UnsafeNativeCodeDetector extends Detector implements Detector.OtherFileScanner, Detector.BinaryResourceScanner {

    public static final Issue ISSUE = Issue.create(
            "UnsafeNativeCodeLocation",
            "Native code outside library directory",
            "In general, application native code should only be placed in the application's " +
            "library directory, not in other locations such as the res or assets directories. " +
            "Placing the code in the library directory provides increased assurance that the " +
            "code will not be tampered with after application installation. Application " +
            "developers should use the features of their development environment to place " +
            "application native libraries into the lib directory of their compiled APKs. " +
            "Embedding non-shared library native executables into applications should be " +
            "avoided when possible.",
            Category.SECURITY,
            6,
            Severity.WARNING,
            new Implementation(UnsafeNativeCodeDetector.class, EnumSet.of(Scope.RESOURCE_FILE_SCOPE, Scope.OTHER_SCOPE))
    );

    @Override
    public EnumSet<Scope> getApplicableFiles() {
        return EnumSet.of(Scope.RESOURCE_FILE_SCOPE, Scope.OTHER_SCOPE);
    }

    @Override
    public void visitFile(Context context, File file) {
        checkNativeFile(context, file);
    }

    @Override
    public void visitBinaryResource(Context context, File file) {
        checkNativeFile(context, file);
    }

    private void checkNativeFile(Context context, File file) {
        String name = file.getName();
        if (name.endsWith(".so")) {
            String path = file.getPath().replace('\\', '/');
            if (path.contains("/res/") || path.contains("/assets/") ||
                path.startsWith("res/") || path.startsWith("assets/")) {
                context.report(ISSUE, Location.create(file),
                        "Native libraries should be placed in the `lib/` or `jniLibs/` directory, " +
                        "not in `res/` or `assets/`.");
            }
        }
    }
}
